import{fetchCohortJSON}from'./current-cohort-loader.js';const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let d,careers={},page=25;const names=ids=>ids.map(id=>h(careers[id]?.title||id)).join('<br>');const bar=(label,n,total)=>n===null?`<div class="short093-bar"><span>${h(label)}</span><b>Not evaluable</b></div>`:`<div class="short093-bar"><span>${h(label)}</span><b>${n} / ${total} · ${(n/total*100).toFixed(1)}%</b><progress value="${n}" max="${total}" aria-label="${h(label)}"></progress></div>`;
function render(){const cohort=$('cohort').value,s=d.summary.find(r=>r.cohort===cohort),rs=d.rows.filter(r=>cohort==='all'?r.cohort!=='grok075':r.cohort===cohort);$('summary').innerHTML=`<h2>Current extensive-answer matches</h2><div class="link-grid">${bar('Supported Top',s.afterTop,s.models)}${bar('College / graduate Top',s.afterDegree,s.models)}</div><p>Saved extensive-answer matches are unchanged. ${s.degreeBelowCap} models have supported degree options outside Top.</p><h2>Fresh start · same profiles, fewer answers</h2><p>${s.typedProfiles===0?'This split is not evaluable with the typed-answer simulator. ':''}${s.typedProfiles} / ${s.models} profiles have structured preference facts for simulation. Other profiles remain unknown. Previous follow-ups withheld; these are not observed student outcomes.</p><div class="link-grid">${[['Before activity-binding repair','shortCurrent'],['Activity bindings + whole-question reuse','shortAnswers'],['Previous targeted prototype','shortTargeted'],['Activity lead + adaptive targeting ·0.94','repaired']].map(([label,key])=>`<section class="feature"><h3>${label}</h3>${bar('Supported Top',s.typedProfiles?s[key].top:null,s.models)}${bar('College / graduate Top',s.typedProfiles?s[key].degree:null,s.models)}<p>${(s[key].questions/s.models).toFixed(1)} questions/model · ${(s[key].unknown/Math.max(1,s[key].questions)*100).toFixed(1)}% unknown · ${s[key].unbound} asked checks lack scoped simulator bindings</p></section>`).join('')}</div><p>${s.typedProfiles?`Compared with the previous targeted arm: ${s.retention.gainedPriorTop.length} gain Top, ${s.retention.lostPriorTop.length} lose Top; ${s.retention.gainedPriorDegree.length} gain college / graduate Top, ${s.retention.lostPriorDegree.length} lose it. These are changed short-flow answers, not losses from current saved plans.`:'No short-flow outcome comparison is available for this split.'}</p>`;
const missing=rs.filter(r=>!r.top.length),degree=rs.filter(r=>!r.degree),unbound=missing.filter(r=>r.review.some(c=>c.missing.some(q=>q[2]))),known=missing.filter(r=>r.review.some(c=>c.missing.some(q=>!q[2]&&q[1]==='unfamiliar')));$('priorities').innerHTML=`<div class="link-grid"><article class="feature"><h3>Must · validate the repaired flow</h3><p>The previous selector skipped direct activity leads. Version 0.94 probes an activity lead, then adapts after each answer. Unfamiliar specific interests are deferred without being rejected. Measure real-student usefulness before changing the live flow.</p></article><article class="feature"><h3>Should · fill exact evidence gaps</h3><p>${unbound.length} no-Top models have an unresolved scoped check among their three inspected candidates. ${known.length} have mapped but unmeasured interests. Ask; do not assume Yes.</p></article><article class="feature"><h3>Could · broaden performance careers</h3><p>Actors, dancers, musicians and choreography remain distinct inventory gaps. Verify performance preferences and irregular-income assumptions before adding matches.</p></article></div><p>${missing.length} without supported Top · ${degree.length} without college/graduate Top. No degree preference or demographic attribute grants an interest.</p>`;
const query=$('search').value.toLowerCase(),issue=$('issue').value,filtered=rs.filter(r=>(issue==='all'||issue==='noTop'&&!r.top.length||issue==='noDegree'&&!r.degree||issue==='changed'&&r.gained.length||issue==='shortNoTop'&&!r.short[3][0]||issue==='shortNoDegree'&&!r.short[3][1])&&(!query||(r.id+' '+r.name).toLowerCase().includes(query)));$('count').textContent=`${filtered.length} models · showing ${Math.min(page,filtered.length)}`;$('models').innerHTML=filtered.slice(0,page).map(r=>`<tr><td><b>${h(r.name)}</b><br>${h(r.id)}<br><a href="/model-journey.html?model=${encodeURIComponent(r.id)}">Saved journey →</a></td><td>${r.top.length} Top<br>${names(r.top)}<br>${r.degree?'College / graduate Top':r.allDegree?'Supported degree option outside Top':'No supported degree option'}${r.gained.length?'<br>New support: '+h(r.gained.join(', ')):''}</td><td>${r.short[3][0]} Top<br>${names(r.short[3][5])}<br>${r.short[3][1]?'College / graduate Top':'No degree Top'}<br>${r.short[3][2]} questions · ${r.short[3][3]} unknown</td><td>${d.manualReview?.find(x=>x.id===r.id)?'<p><b>Profile review:</b> '+h(d.manualReview.find(x=>x.id===r.id).finding)+'</p><p><b>Focused question:</b> '+h(d.manualReview.find(x=>x.id===r.id).question)+'</p>':''}${r.review.map(c=>`<details><summary>${h(careers[c.id]?.title||c.id)} · ${c.domains} specific + ${c.taskDomains} task domains</summary><ul>${c.missing.map(([q,a,unbound,newBinding])=>`<li>${h(d.questions[q].prompt)}<br><b>${unbound?'Scoped binding needs review':a==='yes'?'Typed evidence available':a==='no'?'Explicitly declined':'Interest remains unknown'}</b>${newBinding?' · new scoped binding':''}</li>`).join('')}</ul></details>`).join('')||(r.top.length?'No unresolved checks reviewed for this model.':'No eligible candidate with unanswered checks; review inventory and explicit declines.')}</td></tr>`).join('');$('more').hidden=page>=filtered.length;}
try{const[data,current,repair]=await Promise.all([fetchCohortJSON('/developer/evidence-093.json.gz'),fetchCohortJSON('/developer/current-students-091.json.gz'),fetchCohortJSON('/developer/evidence-094.json.gz')]);d=data;const fixed=new Map(repair.rows.map(r=>[r[0],r]));for(const s of d.summary){const fix=repair.summary.find(r=>r.cohort===s.cohort);s.repaired=fix.repaired;s.retention=fix;}for(const r of d.rows){const f=fixed.get(r.id);r.short.push([f[1].length,f[2],f[3],f[4],f[5],f[1]]);}d.limits.push(...repair.limits);const modelNames=new Map(current.rows.map(r=>[r.id,r.name]));d.rows=d.rows.map(r=>({...r,name:modelNames.get(r.id)||r.id}));careers={...current.catalog,...d.shortCareers,...repair.careers};const params=new URL(location.href).searchParams;if([...$('cohort').options].some(o=>o.value===params.get('cohort')))$('cohort').value=params.get('cohort');if(params.get('model')){$('search').value=params.get('model');$('issue').value='all';}$('limits').innerHTML=d.limits.map(l=>'<li>'+h(l)+'</li>').join('');render();for(const id of['cohort','issue','search'])$(id).addEventListener('input',()=>{page=25;render();});$('more').onclick=()=>{page+=25;render();};}catch(e){$('summary').textContent=e.message;}
